1	"use server";
2	
3	/**
4	 * ADMIN-only actions for the free Minecraft product — a separate surface from
5	 * lib/actions-free-minecraft.ts (the customer-facing actions, which all resolve
6	 * "the caller's own server" via `requireUser()` + `userId`). Admins need to
7	 * operate on ANY server by id, so every export here re-checks `requireArea("fleet")`
8	 * itself (never trust the UI alone) and looks the row up by `id`, not by caller.
9	 *
10	 * `"use server"` means every export is a network-reachable endpoint.
11	 */
12	import { revalidatePath } from "next/cache";
13	import { db } from "./db";
14	import { requireArea } from "./rbac";
15	import { withServerSsh, exec, shellQuote } from "./ssh-exec";
16	import { getFreeServerStatus } from "./free-minecraft-control";
17	import type { SftpServer } from "./sftp";
18	
19	type Result = { ok?: boolean; error?: string };
20	
21	/** Same dedicated Docker host lib/actions-free-minecraft.ts talks to — a real
22	 *  Server row (hostname="freemc-host"), not a customer VPS. */
23	async function freemcHost(): Promise<SftpServer> {
24	  const host = await db.server.findFirst({
25	    where: { hostname: "freemc-host" },
26	    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
27	  });
28	  if (!host) throw new Error("Free Minecraft host is not provisioned.");
29	  return host;
30	}
31	
32	/** Lazy, on-demand live status for one server (running + player count) — the
33	 *  list page deliberately does NOT fetch this for every row on load (see
34	 *  app/admin/free-minecraft/page.tsx's header note); this backs a per-row
35	 *  "check status" button instead. */
36	export async function adminGetFreeMinecraftStatus(
37	  id: string
38	): Promise<{ ok: true; running: boolean; players: { online: number; max: number } | null } | { ok: false; error: string }> {
39	  await requireArea("fleet");
40	  const row = await db.freeMinecraftServer.findUnique({ where: { id }, select: { containerName: true } });
41	  if (!row) return { ok: false, error: "Server not found." };
42	
43	  try {
44	    const host = await freemcHost();
45	    const status = await withServerSsh(host, (conn) => getFreeServerStatus(conn, row.containerName));
46	    return { ok: true, running: status.running, players: status.players };
47	  } catch (e) {
48	    console.error("[admin-freemc] status check failed:", e);
49	    return { ok: false, error: "Could not reach the free Minecraft host." };
50	  }
51	}
52	
53	/**
54	 * Force a server's public listing off — a moderation lever for a listing that
55	 * needs to be pulled (abuse report, inappropriate tagline/description, etc.)
56	 * without deleting the server or touching its container.
57	 */
58	export async function adminUnpublishFreeMinecraftServer(id: string): Promise<Result> {
59	  const admin = await requireArea("fleet");
60	  const row = await db.freeMinecraftServer.findUnique({ where: { id }, select: { id: true, isPublic: true } });
61	  if (!row) return { error: "Server not found." };
62	  if (!row.isPublic) return { ok: true };
63	
64	  await db.freeMinecraftServer.update({ where: { id }, data: { isPublic: false } });
65	  await db.auditLog.create({
66	    data: { userId: admin.id, action: "admin.freemc_unpublish", detail: id },
67	  });
68	  revalidatePath("/admin/free-minecraft");
69	  return { ok: true };
70	}
71	
72	/**
73	 * Delete a stray/abandoned free server: `docker rm -f` its container + wipe its
74	 * data dir on freemc-host, then remove the DB row. Same cleanup shape as the
75	 * customer-facing `deleteFreeMinecraftServer` in lib/actions-free-minecraft.ts,
76	 * but admin-gated and looked up by `id` (any server), not by the caller's own
77	 * userId. The DB row is removed even if the SSH cleanup fails — a stuck row
78	 * that no longer resolves to a real container is worse than an orphaned
79	 * container directory an admin can still clean up by hand.
80	 */
81	export async function adminDeleteFreeMinecraftServer(id: string): Promise<Result> {
82	  const admin = await requireArea("fleet");
83	  const row = await db.freeMinecraftServer.findUnique({
84	    where: { id },
85	    select: { id: true, containerName: true, subdomain: true },
86	  });
87	  if (!row) return { error: "Server not found." };
88	
89	  try {
90	    const host = await freemcHost();
91	    await withServerSsh(host, async (conn) => {
92	      await exec(conn, `docker rm -f ${shellQuote(row.containerName)}`, 30_000);
93	      await exec(conn, `rm -rf ${shellQuote(`/opt/freemc/servers/${row.id}`)}`, 15_000);
94	    });
95	  } catch (e) {
96	    console.error("[admin-freemc] delete cleanup failed (row is removed regardless):", e);
97	  }
98	
99	  await db.freeMinecraftServer.delete({ where: { id } });
100	  await db.auditLog.create({
101	    data: { userId: admin.id, action: "admin.freemc_delete", detail: `${id} (${row.subdomain})` },
102	  });
103	  revalidatePath("/admin/free-minecraft");
104	  return { ok: true };
105	}
