1	"use server";
2	
3	/**
4	 * The two-axis free-Minecraft model: GAME TYPE (which isolated, persistent
5	 * world — vanilla/skyblock/prison/...) and GAME MODE (survival/hardcore/
6	 * creative/peaceful, a lightweight properties overlay applied WITHIN
7	 * whichever type is active). See lib/free-minecraft-control.ts's big
8	 * module-doc comment above FREEMC_GAME_TYPES for the full architecture note,
9	 * including the live LEVEL-isolation verification this is built on.
10	 *
11	 * Deliberately a separate file/module from lib/actions-free-minecraft.ts,
12	 * matching the file-isolation convention already established by
13	 * lib/actions-freemc-mods.ts and lib/actions-freemc-roles.ts in this same
14	 * feature area — freemcHost() below is a deliberate, identical duplicate of
15	 * that file's private helper (not exported there) rather than a cross-file
16	 * import.
17	 *
18	 * lib/actions-free-minecraft.ts's applyFreeMinecraftPreset is kept alive as a
19	 * DEPRECATED, backward-compatible entry point for the not-yet-migrated
20	 * dashboard UI (components/customer/freemc/*.tsx) — it now delegates to the
21	 * exact same recreateGameTypeContainer/applyModeProperties machinery this
22	 * file uses, so a world switched from either surface is isolated identically.
23	 * New UI should call the two exports below instead.
24	 */
25	import { revalidatePath } from "next/cache";
26	import { db } from "./db";
27	import { requireUser } from "./auth";
28	import { checkRateLimit } from "./rate-limit";
29	import { getSetting, getSettingInt } from "./settings";
30	import { withServerSsh, exec, shellQuote } from "./ssh-exec";
31	import type { SftpServer } from "./sftp";
32	import {
33	  FREEMC_GAME_TYPES,
34	  FREEMC_GAME_MODES,
35	  legacyPresetKeyFor,
36	  recreateGameTypeContainer,
37	  applyModeProperties,
38	} from "./free-minecraft-control";
39	
40	type Result = { error?: string };
41	
42	/** Same target as lib/actions-free-minecraft.ts's freemcHost() — that helper
43	 *  isn't exported, so this is a deliberate, identical duplicate rather than a
44	 *  cross-file import, matching the file-isolation convention already used by
45	 *  lib/actions-freemc-mods.ts. */
46	async function freemcHost(): Promise<SftpServer> {
47	  const host = await db.server.findFirst({
48	    where: { hostname: "freemc-host" },
49	    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
50	  });
51	  if (!host) throw new Error("Free Minecraft host is not provisioned.");
52	  return host;
53	}
54	
55	/**
56	 * One row per game type the caller's account has ever actually applied — a
57	 * world only "exists" once that type has been switched to at least once, so
58	 * a brand-new or not-yet-migrated account can legitimately show an empty
59	 * list (see the schema note on FreeMinecraftServer.activeGameType: existing,
60	 * already-deployed rows default to "vanilla" but won't have a
61	 * FreeMinecraftWorld row until they're actually switched to through this
62	 * file or through the legacy applyFreeMinecraftPreset).
63	 */
64	export type FreeMcWorld = { gameType: string; label: string; lastPlayedAt: string | null; isActive: boolean };
65	
66	export async function listFreeMinecraftWorlds(): Promise<
67	  | { ok: true; worlds: FreeMcWorld[] }
68	  | { ok: false; error: string }
69	> {
70	  const user = await requireUser();
71	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
72	  if (!row) return { ok: false, error: "You don't have a free server." };
73	
74	  const worlds = await db.freeMinecraftWorld.findMany({
75	    where: { serverId: row.id },
76	    orderBy: { lastPlayedAt: "desc" },
77	  });
78	
79	  return {
80	    ok: true,
81	    worlds: worlds.map((w) => ({
82	      gameType: w.gameType,
83	      label: w.label || FREEMC_GAME_TYPES[w.gameType]?.label || w.gameType,
84	      lastPlayedAt: w.lastPlayedAt ? w.lastPlayedAt.toISOString() : null,
85	      isActive: w.gameType === row.activeGameType,
86	    })),
87	  };
88	}
89	
90	/**
91	 * Switches which GAME TYPE (isolated world) is loaded — a full container
92	 * recreate with the target type's `-e LEVEL=<gameType>`, same rollback-on-
93	 * failure discipline as the old flat-preset code (see
94	 * lib/actions-free-minecraft.ts's applyFreeMinecraftPreset for the incident
95	 * history that discipline exists to prevent). Preserves whatever GAME MODE
96	 * is currently active — a type switch must never silently reset the mode
97	 * (confirmed live, see free-minecraft-control.ts). Lazily creates the
98	 * FreeMinecraftWorld row on a type's first-ever visit; every other type is
99	 * simply never touched.
100	 */
101	export async function switchFreeMinecraftGameType(_prev: unknown, formData: FormData): Promise<Result> {
102	  const user = await requireUser();
103	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
104	  if (!row) return { error: "You don't have a free server." };
105	
106	  const gameType = String(formData.get("gameType") ?? "");
107	  const targetType = FREEMC_GAME_TYPES[gameType];
108	  if (!targetType) return { error: "Unknown game type." };
109	
110	  const rl = checkRateLimit(`freemc:gametype:${user.id}`, { max: 10, windowMs: 60_000 });
111	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
112	
113	  const activeMode = FREEMC_GAME_MODES[row.activeGameMode] ?? FREEMC_GAME_MODES.survival;
114	  const now = new Date();
115	
116	  if (gameType === row.activeGameType) {
117	    // Already here — just a re-visit, not a real switch. Touch the world's
118	    // lastPlayedAt (creating the row if this is somehow the first time it's
119	    // been recorded) without going anywhere near the container.
120	    await db.freeMinecraftWorld.upsert({
121	      where: { serverId_gameType: { serverId: row.id, gameType } },
122	      update: { lastPlayedAt: now },
123	      create: { serverId: row.id, gameType, label: targetType.label, lastPlayedAt: now },
124	    });
125	    revalidatePath("/dashboard/free-minecraft");
126	    return {};
127	  }
128	
129	  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
130	  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
131	  const previousTypeKey = FREEMC_GAME_TYPES[row.activeGameType] ? row.activeGameType : "vanilla";
132	  const previousType = FREEMC_GAME_TYPES[previousTypeKey];
133	
134	  try {
135	    const host = await freemcHost();
136	    const outcome = await withServerSsh(host, async (conn) => {
137	      // Same reasoning as the legacy preset switch: plugin jars from the
138	      // PREVIOUS type must be cleared, or itzg's entrypoint syncs the new
139	      // type's env against a plugins/ dir still full of the old type's jars.
140	      await exec(conn, `docker exec ${shellQuote(row.containerName)} sh -c 'rm -rf /data/plugins/*'`, 15_000).catch(() => {});
141	      const applied = await recreateGameTypeContainer(conn, {
142	        containerName: row.containerName,
143	        dataPath: `/opt/freemc/servers/${row.id}`,
144	        subdomain: row.subdomain,
145	        domain,
146	        ramMb,
147	        ownerId: user.id,
148	        gameType: targetType,
149	        gameTypeKey: gameType,
150	        gameMode: activeMode,
151	      });
152	      if (applied.ok) return { ok: true as const };
153	
154	      console.error("[freemc-worlds] game type switch failed, rolling back:", applied.error);
155	      const rolledBack = await recreateGameTypeContainer(conn, {
156	        containerName: row.containerName,
157	        dataPath: `/opt/freemc/servers/${row.id}`,
158	        subdomain: row.subdomain,
159	        domain,
160	        ramMb,
161	        ownerId: user.id,
162	        gameType: previousType,
163	        gameTypeKey: previousTypeKey,
164	        gameMode: activeMode,
165	      });
166	      return rolledBack.ok
167	        ? { ok: false as const, error: "That game type didn't start cleanly, so we put your server back the way it was." }
168	        : { ok: false as const, error: "That game type didn't start, and restoring your previous one also failed — please contact support." };
169	    });
170	    if (!outcome.ok) return { error: outcome.error };
171	  } catch (e) {
172	    console.error("[freemc-worlds] switch game type failed:", e);
173	    return { error: "Couldn't switch game type — please try again." };
174	  }
175	
176	  await db.freeMinecraftServer.update({
177	    where: { id: row.id },
178	    data: { activeGameType: gameType, preset: legacyPresetKeyFor(gameType, row.activeGameMode) },
179	  });
180	  await db.freeMinecraftWorld.upsert({
181	    where: { serverId_gameType: { serverId: row.id, gameType } },
182	    update: { lastPlayedAt: now },
183	    create: { serverId: row.id, gameType, label: targetType.label, lastPlayedAt: now },
184	  });
185	  revalidatePath("/dashboard/free-minecraft");
186	  return {};
187	}
188	
189	/**
190	 * Applies a GAME MODE overlay (gamemode/hardcore/difficulty) to whichever
191	 * world is currently active — RCON + a restart of the SAME container, never
192	 * a recreate, never touches LEVEL or any other world's data. See
193	 * free-minecraft-control.ts's applyModeProperties for why the 3 properties
194	 * this touches are deliberately never baked as container env vars (confirmed
195	 * live: they'd get silently reasserted on every restart otherwise, which
196	 * would break exactly this action).
197	 */
198	export async function applyFreeMinecraftGameMode(_prev: unknown, formData: FormData): Promise<Result> {
199	  const user = await requireUser();
200	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
201	  if (!row) return { error: "You don't have a free server." };
202	
203	  const gameMode = String(formData.get("gameMode") ?? "");
204	  const mode = FREEMC_GAME_MODES[gameMode];
205	  if (!mode) return { error: "Unknown game mode." };
206	
207	  const rl = checkRateLimit(`freemc:gamemode:${user.id}`, { max: 10, windowMs: 60_000 });
208	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
209	
210	  if (gameMode === row.activeGameMode) return {};
211	
212	  try {
213	    const host = await freemcHost();
214	    await withServerSsh(host, async (conn) => {
215	      const applied = await applyModeProperties(conn, row.containerName, user.id, mode);
216	      if (!applied.ok) throw new Error(applied.error || "Could not apply game mode.");
217	    });
218	  } catch (e) {
219	    console.error("[freemc-worlds] apply game mode failed:", e);
220	    return { error: "Couldn't apply that game mode — please try again." };
221	  }
222	
223	  await db.freeMinecraftServer.update({
224	    where: { id: row.id },
225	    data: { activeGameMode: gameMode, preset: legacyPresetKeyFor(row.activeGameType, gameMode) },
226	  });
227	  revalidatePath("/dashboard/free-minecraft");
228	  return {};
229	}
230	
231	export async function renameFreeMinecraftWorld(_prev: unknown, formData: FormData): Promise<Result> {
232	  const user = await requireUser();
233	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
234	  if (!row) return { error: "You don't have a free server." };
235	
236	  const gameType = String(formData.get("gameType") ?? "");
237	  if (!FREEMC_GAME_TYPES[gameType]) return { error: "Unknown game type." };
238	
239	  const label = String(formData.get("label") ?? "").trim().slice(0, 40);
240	  if (!label) return { error: "Enter a name." };
241	
242	  // db.freeMinecraftWorld.update({where:{serverId_gameType:...}}) IS the
243	  // ownership check here, same pattern as every other free-Minecraft action:
244	  // a world row can only ever be found under the caller's own server.
245	  try {
246	    await db.freeMinecraftWorld.update({
247	      where: { serverId_gameType: { serverId: row.id, gameType } },
248	      data: { label },
249	    });
250	  } catch {
251	    return { error: "That world doesn't exist yet — switch to it first." };
252	  }
253	  revalidatePath("/dashboard/free-minecraft");
254	  return {};
255	}
256	
257	/**
258	 * Deletes one game type's saved world — refuses if it's the currently-active
259	 * type (switch away first, or the container would be pointed at a world that
260	 * no longer exists). Removes exactly `<gameType>`, `<gameType>_nether`,
261	 * `<gameType>_the_end`, plus any plugin-specific custom dimension folders
262	 * that don't follow the LEVEL-based naming scheme (see
263	 * FreeMcGameType.extraWorldFolders — confirmed live that IridiumSkyblock's
264	 * `iridiumskyblock*` dimensions are one such case). Every path removed is an
265	 * exact, individually shell-quoted folder name under this server's own data
266	 * dir, never a glob and never the bare data dir itself, so this can never
267	 * remove anything but this one type's own world data.
268	 */
269	export async function deleteFreeMinecraftWorld(_prev: unknown, formData: FormData): Promise<Result> {
270	  const user = await requireUser();
271	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
272	  if (!row) return { error: "You don't have a free server." };
273	
274	  const gameType = String(formData.get("gameType") ?? "");
275	  const type = FREEMC_GAME_TYPES[gameType];
276	  if (!type) return { error: "Unknown game type." };
277	
278	  if (gameType === row.activeGameType) {
279	    return { error: "You can't delete the world you're currently playing on — switch to a different game type first." };
280	  }
281	
282	  const rl = checkRateLimit(`freemc:deleteworld:${user.id}`, { max: 10, windowMs: 60_000 });
283	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
284	
285	  const world = await db.freeMinecraftWorld.findUnique({ where: { serverId_gameType: { serverId: row.id, gameType } } });
286	  if (!world) return { error: "That world doesn't exist." };
287	
288	  try {
289	    const host = await freemcHost();
290	    const dataPath = `/opt/freemc/servers/${row.id}`;
291	    const folders = [gameType, `${gameType}_nether`, `${gameType}_the_end`, ...(type.extraWorldFolders ?? [])];
292	    await withServerSsh(host, async (conn) => {
293	      for (const folder of folders) {
294	        await exec(conn, `rm -rf ${shellQuote(`${dataPath}/${folder}`)}`, 15_000);
295	      }
296	    });
297	  } catch (e) {
298	    // Best-effort disk cleanup, same tolerance as deleteFreeMinecraftServer —
299	    // the DB row (what the customer actually sees) is removed regardless, so
300	    // a transient SSH failure never leaves a "delete" that silently no-ops.
301	    console.error("[freemc-worlds] world folder cleanup failed (row removed regardless):", e);
302	  }
303	
304	  await db.freeMinecraftWorld.delete({ where: { id: world.id } });
305	  revalidatePath("/dashboard/free-minecraft");
306	  return {};
307	}
