79	export async function createFreeMinecraftServer(_prev: unknown, formData: FormData): Promise<Result> {
80	  const user = await requireUser();
81	  const subdomain = String(formData.get("subdomain") ?? "");
82	
83	  // Prefer the new two-axis fields (the UI being built in parallel sends
84	  // these); fall back to the legacy flat `preset` field the current create
85	  // form (components/customer/FreeMinecraftPanel.tsx) still submits, so
86	  // account creation keeps working unbroken through the UI migration.
87	  // Defaults to gameType=vanilla, gameMode=survival either way.
88	  const gameTypeField = formData.get("gameType");
89	  const gameModeField = formData.get("gameMode");
90	  let gameType = "vanilla";
91	  let gameMode = "survival";
92	  if (typeof gameTypeField === "string" && FREEMC_GAME_TYPES[gameTypeField]) {
93	    gameType = gameTypeField;
94	    if (typeof gameModeField === "string" && FREEMC_GAME_MODES[gameModeField]) gameMode = gameModeField;
95	  } else {
96	    const mapped = mapLegacyPresetKey(String(formData.get("preset") ?? "vanilla"));
97	    if (mapped) ({ gameType, gameMode } = mapped);
98	  }
99	  const gameTypeDef = FREEMC_GAME_TYPES[gameType];
100	  const gameModeDef = FREEMC_GAME_MODES[gameMode];
101	
102	  if (!(await getSettingBool("free_minecraft_enabled", false))) {
103	    return { error: "Free Minecraft servers aren't open yet — check back soon." };
104	  }
105	
106	  try {
107	    await assertEmailVerified(user);
108	  } catch {
109	    return { error: "Verify your email first — check your inbox for the link." };
110	  }
111	
112	  const rl = checkRateLimit(`freemc:create:${user.id}`, { max: 5, windowMs: 60_000 });
113	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
114	
115	  const sub = subdomain.trim().toLowerCase();
116	  if (!SUBDOMAIN_RE.test(sub) || RESERVED.has(sub)) {
117	    return { error: "Pick a name: 3-20 lowercase letters, numbers, or hyphens, not a reserved word." };
118	  }
119	
120	  const existing = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
121	  if (existing) return { error: "You already have a free server. Delete it before creating another." };
122	
123	  const maxTotal = await getSettingInt("free_minecraft_max_concurrent", 8);
124	  const total = await db.freeMinecraftServer.count({ where: { status: { not: "DELETED" } } });
125	  if (total >= maxTotal) {
126	    return { error: "Free servers are at capacity right now — please try again later." };
127	  }
128	
129	  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
130	  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
131	
132	  // Derived from userId (unique, known up front) rather than the row's own id,
133	  // so creation is a single write — no awkward "create with a placeholder,
134	  // then patch in the real name" two-phase step that could race.
135	  const containerName = `mc-free-${user.id}`;
136	  let row;
137	  try {
138	    row = await db.freeMinecraftServer.create({
139	      data: {
140	        userId: user.id,
141	        subdomain: sub,
142	        containerName,
143	        status: "CREATING",
144	        activeGameType: gameType,
145	        activeGameMode: gameMode,
146	        preset: legacyPresetKeyFor(gameType, gameMode),
