  ownerEmail: string | null;
  gameType: string;
  gameTypeLabel: string;
};

export type FreemcCapacitySnapshot = {
  totalCpus: number;
  totalRamMb: number;
  committedCpus: number;
  committedRamMb: number;
  reservedCpus: number;
  reservedRamMb: number;
  containers: FreemcCapacityContainer[];
};

/**
 * Live host-level capacity snapshot for the admin resource-usage view — see
 * lib/freemc-capacity.ts for the accounting (nproc/free -m for host totals,
 * `docker inspect` per running mc-free-* container for what's actually
 * assigned) and lib/free-minecraft-control.ts's recreateGameTypeContainer /
 * lib/actions-free-minecraft.ts's powerAction for where the same helper
 * GATES a customer-triggered start. This is read-only — it never starts,
 * stops, or otherwise touches a container, just reports what's already true.
 *
 * Resolves each running container's raw name back to its owning customer +
 * active game type via FreeMinecraftServer.containerName, so the admin view
 * shows something meaningful instead of a bare `mc-free-<userId>` string. A
 * container with no matching DB row (shouldn't normally happen, but SSH/DB
 * can disagree transiently) still shows up with null owner fields rather
 * than being silently dropped — an admin diagnosing a capacity problem needs
 * to see every running container, matched or not.
 */
export async function adminGetFreemcHostCapacity(): Promise<
  { ok: true; snapshot: FreemcCapacitySnapshot } | { ok: false; error: string }
> {
  await requireArea("fleet");

  try {
    const host = await freemcHost();
    const cap = await withServerSsh(host, (conn) => getFreemcHostCapacity(conn));

    const containerNames = cap.runningContainers.map((c) => c.containerName);
    const rows = containerNames.length
      ? await db.freeMinecraftServer.findMany({
          where: { containerName: { in: containerNames } },
          select: {
            containerName: true,
            activeGameType: true,
            userId: true,
            user: { select: { name: true, email: true } },
          },
        })
      : [];
    const byContainer = new Map(rows.map((r) => [r.containerName, r]));

    const containers: FreemcCapacityContainer[] = cap.runningContainers.map((c) => {
      const row = byContainer.get(c.containerName);
      return {
        containerName: c.containerName,
        cpus: c.cpus,
        ramMb: c.ramMb,
        startedAt: c.startedAt,
        ownerId: row?.userId ?? null,
        ownerName: row?.user.name ?? null,
        ownerEmail: row?.user.email ?? null,
        gameType: row?.activeGameType ?? "unknown",
        gameTypeLabel: (row ? FREEMC_GAME_TYPES[row.activeGameType]?.label : undefined) ?? row?.activeGameType ?? "Unknown",
      };
    });

    return {
      ok: true,
      snapshot: {
        totalCpus: cap.totalCpus,
        totalRamMb: cap.totalRamMb,
        committedCpus: cap.committedCpus,
        committedRamMb: cap.committedRamMb,
        reservedCpus: FREEMC_RESERVED_CPUS,
        reservedRamMb: FREEMC_RESERVED_RAM_MB,
        containers,
      },
    };
  } catch (e) {
    console.error("[admin-freemc] capacity check failed:", e);
    return { ok: false, error: "Could not reach the free Minecraft host." };
  }
}

