/**
 * Host-level CPU/RAM resource-usage view for the admin free-Minecraft panel —
 * backs the same capacity accounting (lib/freemc-capacity.ts) that gates a
 * customer-triggered container start (recreateGameTypeContainer, powerAction
 * "start"/"restart"), so an admin can see exactly why a customer might be
 * getting the "at capacity" error and who's actually using what right now.
 *
 * A simple fetch-on-mount + refresh-on-focus + manual button, not a live
 * websocket — this is an admin diagnostic view, the same tradeoff
 * CheckStatusButton above already makes for per-row live status.
 */
export function FreemcCapacityPanel({ thresholds }: { thresholds: NodeThresholds }) {
  const [snapshot, setSnapshot] = useState<FreemcCapacitySnapshot | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(() => {
    start(async () => {
      const res = await adminGetFreemcHostCapacity();
      if (!res.ok) {
        setError(res.error);
        return;
      }
      setError(null);
      setSnapshot(res.snapshot);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    refresh();
    const onFocus = () => refresh();
    window.addEventListener("focus", onFocus);
    return () => window.removeEventListener("focus", onFocus);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="card p-5">
      <div className="flex items-start justify-between gap-4">
        <div>
          <h2 className="font-semibold">freemc-host capacity</h2>
          <p className="mt-0.5 text-xs text-slate-400">
            Live CPU/RAM commitment on the shared Docker host — the same numbers that gate a customer-triggered
            container start (create, switch game type, manual dashboard start). mc-router&apos;s own passive
            wake-on-connect isn&apos;t gated by this — it acts on its own, outside this app.
          </p>
        </div>
        <button className="btn-ghost shrink-0 py-1 text-xs" disabled={pending} onClick={refresh}>
          {pending ? "Refreshing…" : "Refresh"}
        </button>
      </div>

      {error && <div className="mt-3 text-xs text-red-400">{error}</div>}

      {snapshot && (
        <>
          <div className="mt-4 grid gap-4 sm:grid-cols-2">
            <CapacityMeter
              label="CPU"
              committed={snapshot.committedCpus}
              total={snapshot.totalCpus}
              reserved={snapshot.reservedCpus}
              unit="vCPU"
              thresholds={thresholds}
            />
            <CapacityMeter
              label="RAM"
              committed={snapshot.committedRamMb}
              total={snapshot.totalRamMb}
              reserved={snapshot.reservedRamMb}
              unit="MB"
              thresholds={thresholds}
            />
          </div>

          <div className="mt-5">
            <h3 className="section-label mb-2">Running containers ({snapshot.containers.length})</h3>
            {snapshot.containers.length === 0 ? (
              <p className="text-xs text-slate-500">No free-tier containers are currently running.</p>
            ) : (
              <div className="overflow-x-auto">
                <table className="table-shell">
                  <thead>
                    <tr>
                      <th>Owner</th>
                      <th>Game type</th>
                      <th>Container</th>
                      <th>CPU</th>
                      <th>RAM</th>
                      <th>Uptime</th>
                    </tr>
                  </thead>
                  <tbody>
                    {snapshot.containers.map((c) => (
                      <tr key={c.containerName}>
                        <td>{c.ownerName || c.ownerEmail || <span className="text-slate-500">unknown</span>}</td>
                        <td>{c.gameTypeLabel}</td>
                        <td className="font-mono text-xs text-slate-400">{c.containerName}</td>
                        <td>{c.cpus} vCPU</td>
                        <td>{c.ramMb} MB</td>
                        <td className="text-xs text-slate-400">{c.startedAt ? timeAgo(new Date(c.startedAt)) : "—"}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </>
      )}

      {!snapshot && !error && <p className="mt-3 text-xs text-slate-500">Loading live host capacity…</p>}
    </div>
  );
}

function formatUnit(n: number, unit: "MB" | "vCPU"): string {
  if (unit === "MB") return n >= 1024 ? `${(n / 1024).toFixed(1)}GB` : `${Math.round(n)}MB`;
  return `${Math.round(n * 100) / 100} vCPU`;
}

function CapacityMeter({
  label,
  committed,
  total,
  reserved,
  unit,
  thresholds,
}: {
  label: string;
  committed: number;
  total: number;
  reserved: number;
  unit: "MB" | "vCPU";
  thresholds: NodeThresholds;
}) {
  const budget = Math.max(total - reserved, 0);
  const pct = budget > 0 ? (committed / budget) * 100 : committed > 0 ? 100 : 0;
  const sev = severityFor(pct, thresholds);
  return (
    <div>
      <div className="mb-1 flex items-center justify-between text-xs">
        <span className="font-medium text-slate-300">{label}</span>
        <span className="text-slate-400">
          {formatUnit(committed, unit)} / {formatUnit(budget, unit)} budget · {formatUnit(total, unit)} total
        </span>
      </div>
      <MeterBar value={Math.min(100, pct)} max={100} color={capBarColor(sev)} />
      <div className="mt-0.5 text-[10px] text-slate-500">
        {Math.round(pct)}% of margined budget ({formatUnit(reserved, unit)} reserved for the host itself)
      </div>
    </div>
  );
}

