/**
 * Pure OK/WARN/CRITICAL severity + meter-color helpers for the shared
 * capacity-warning convention (compute nodes, hosting nodes, and now
 * freemc-host — see app/admin/nodes/page.tsx and
 * components/admin/FreeMinecraftControls.tsx's FreemcCapacityPanel).
 *
 * Split out of lib/node-capacity.ts specifically so this stays CLIENT-SAFE:
 * node-capacity.ts pulls in lib/monitoring.ts -> lib/proxmox.ts -> undici,
 * which bundles Node built-ins (node:crypto, node:async_hooks, ...) that
 * break a "use client" component's webpack bundle if imported transitively.
 * These few functions have zero dependencies of their own, so they're safe
 * for both a client component's live-polled meters and every existing
 * server-side caller. node-capacity.ts re-exports all of this unchanged so
 * no existing import path breaks.
 */
export type CapSeverity = "OK" | "WARN" | "CRITICAL";
export type NodeThresholds = { warnPct: number; critPct: number };

/** Bucket a utilization percent into OK / WARN / CRITICAL. */
export function severityFor(pct: number, t: NodeThresholds): CapSeverity {
  if (pct >= t.critPct) return "CRITICAL";
  if (pct >= t.warnPct) return "WARN";
  return "OK";
}

export function capBarColor(sev: CapSeverity): string {
  if (sev === "CRITICAL") return "#ef4444";
  if (sev === "WARN") return "#f59e0b";
  return "#34d399";
}

