import { db } from "./lib/db";
import { withServerSsh, exec, shellQuote } from "./lib/ssh-exec";
import { getFreemcHostCapacity, wouldExceedFreemcCapacity, FREEMC_RESERVED_CPUS, FREEMC_RESERVED_RAM_MB } from "./lib/freemc-capacity";

async function main() {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("freemc-host not found");
  const name = "mc-free-cmrztujaw0002hlazl58i3lsi";

  await withServerSsh(host, async (conn) => {
    // Confirm starting state: stopped (matches what test-capacity.ts found originally)
    console.log("--- initial state ---");
    console.log((await exec(conn, `docker inspect -f '{{.State.Running}}' ${shellQuote(name)}`, 10_000)).stdout);

    // Simulate the powerAction "start" gate logic exactly.
    const assigned = await exec(conn, `docker inspect ${shellQuote(name)} --format '{{.HostConfig.NanoCpus}} {{.HostConfig.Memory}}'`, 10_000);
    const [nanoCpusRaw, memBytesRaw] = assigned.stdout.trim().split(/\s+/);
    const cpus = (Number.parseInt(nanoCpusRaw, 10) || 0) / 1e9;
    const ramMb = Math.round((Number.parseInt(memBytesRaw, 10) || 0) / (1024 * 1024));
    console.log("assigned cpus/ramMb for this stopped container:", cpus, ramMb);

    const capBefore = await getFreemcHostCapacity(conn);
    console.log("capacity before start (should show 0 committed, container stopped):", JSON.stringify(capBefore));
    const check1 = wouldExceedFreemcCapacity(capBefore, cpus, ramMb);
    console.log("gate check with nothing else running -> should ALLOW:", check1);

    // Now simulate ANOTHER plugin-kind container already running (2 cpu, 2560mb)
    // by starting the real one first, then re-checking as if a SECOND plugin
    // container were about to start (using the just-verified assigned cpus/ram
    // of THIS SAME container as a stand-in "new" container request).
    console.log("--- starting it for real to occupy capacity ---");
    console.log(await exec(conn, `docker start ${shellQuote(name)}`, 30_000));
    await new Promise((r) => setTimeout(r, 3000));

    const capAfter = await getFreemcHostCapacity(conn);
    console.log("capacity after starting it (should show it committed):", JSON.stringify(capAfter));

    const check2 = wouldExceedFreemcCapacity(capAfter, cpus, ramMb);
    console.log("gate check for a SECOND same-size container while first is running -> should BLOCK:", check2);

    console.log("reserved margins:", FREEMC_RESERVED_CPUS, FREEMC_RESERVED_RAM_MB);

    console.log("--- restoring to original stopped state ---");
    console.log(await exec(conn, `docker stop ${shellQuote(name)}`, 30_000));
    console.log((await exec(conn, `docker inspect -f '{{.State.Running}}' ${shellQuote(name)}`, 10_000)).stdout);
  });
  process.exit(0);
}

main().catch((e) => { console.error(e); process.exit(1); });
EOF
